pm.test("Registration returns 201", function () {
    pm.response.to.have.status(201);
});

const response = pm.response.json();

pm.test("Registration always creates PLAYER", function () {
    pm.expect(response.user.role).to.eql("PLAYER");
});

pm.test("Password hash is not exposed", function () {
    pm.expect(response.user).to.not.have.property("password_hash");
});

pm.test("Duplicate school ID returns 409", function () {
