pm.test("ADMIN can list users", function () {
    pm.response.to.have.status(200);
});

pm.test("Users are returned", function () {
    const response = pm.response.json();
    pm.expect(response.users).to.be.an("array");
    pm.expect(response.users.length).to.be.above(0);
});

pm.test("Password hashes are not exposed", function () {
    const response = pm.response.json();

    response.users.forEach(function (user) {
        pm.expect(user).to.not.have.property("password_hash");
    });
});

